#include <vector>
#include <cmath>
#include <stdexcept>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) {
        throw std::invalid_argument("b size must equal N");
    }

    x.assign(N, 0.0);

    // Build dense augmented matrix [A|b] for robust pivoting/solving.
    // (Keeps correctness under all thread counts; assembly is parallelized safely.)
    std::vector<double> M(N * (N + 1), 0.0);

    // Parallel COO -> dense accumulation (safe for duplicate COO entries via atomic).
    #pragma omp parallel for schedule(static)
    for (long long k = 0; k < static_cast<long long>(A.size()); ++k) {
        const COOElement &e = A[static_cast<size_t>(k)];
        if (e.row >= N || e.column >= N) continue;
        const size_t idx = e.row * (N + 1) + e.column;
        #pragma omp atomic update
        M[idx] += e.value;
    }

    // Set RHS column in parallel.
    #pragma omp parallel for schedule(static)
    for (long long i = 0; i < static_cast<long long>(N); ++i) {
        M[static_cast<size_t>(i) * (N + 1) + N] = b[static_cast<size_t>(i)];
    }

    const double eps = 1e-14;

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Pivot search (sequential for simplicity/correctness).
        size_t piv = k;
        double maxAbs = std::fabs(M[k * (N + 1) + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(M[i * (N + 1) + k]);
            if (v > maxAbs) {
                maxAbs = v;
                piv = i;
            }
        }

        if (maxAbs < eps) {
            throw std::runtime_error("Matrix is singular or ill-conditioned");
        }

        // Swap rows if needed (sequential).
        if (piv != k) {
            for (size_t j = k; j <= N; ++j) {
                std::swap(M[k * (N + 1) + j], M[piv * (N + 1) + j]);
            }
        }

        // Eliminate rows below pivot in parallel; each thread writes distinct rows.
        #pragma omp parallel for schedule(static)
        for (long long ii = static_cast<long long>(k) + 1; ii < static_cast<long long>(N); ++ii) {
            size_t i = static_cast<size_t>(ii);
            double factor = M[i * (N + 1) + k] / M[k * (N + 1) + k];
            M[i * (N + 1) + k] = 0.0;
            for (size_t j = k + 1; j <= N; ++j) {
                M[i * (N + 1) + j] -= factor * M[k * (N + 1) + j];
            }
        }
    }

    // Back substitution (sequential due to dependency chain).
    for (long long ii = static_cast<long long>(N) - 1; ii >= 0; --ii) {
        size_t i = static_cast<size_t>(ii);
        double sum = M[i * (N + 1) + N];
        for (size_t j = i + 1; j < N; ++j) {
            sum -= M[i * (N + 1) + j] * x[j];
        }
        double diag = M[i * (N + 1) + i];
        if (std::fabs(diag) < eps) {
            throw std::runtime_error("Matrix is singular during back substitution");
        }
        x[i] = sum / diag;
    }
}
